def seats(tok): return sorted(k for k, ws in BARE.items() if tok in ws)
def run_seats(run):
    ws = run.split(); return sorted(k for k, vv in BARE.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
def ttok(tok): return sorted(k for k, ws in TAN.items() if tok in ws)
def trun(run):
    ws = run.split(); return sorted(k for k, vv in TAN.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
def ptok(tok): return sorted(k for k, ws in TAN.items() if k[0] in TORAH and tok in ws)
def prun(run):
    ws = run.split(); return sorted(k for k, vv in TAN.items() if k[0] in TORAH and any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
FAIL = []
def H(ch, vs, run, en):
    ws, want = BARE[(ch, vs)], run.split()
    idx = [i for i in range(len(ws) - len(want) + 1) if ws[i:i + len(want)] == want]
    if not idx:
        FAIL.append(('RUN NOT IN VERSE', ch, vs, run, ' '.join(ws))); return '?'
    return '%s (%s — Gen %d:%d)' % (' '.join(POINT[(ch, vs)][idx[0]:idx[0] + len(want)]), en, ch, vs)
